# Source of truth for the 20 questions (EN + AR). Run build_seed.py to generate supabase/seed.sql.
# Each question: (stage, category_slug, correct_index, EN, AR); EN/AR = (scenario, [4 options], threat, lesson, [4 "why risky" notes, "" for the correct one])
CATS = {
 "phishing": ("Phishing", "التصيّد الاحتيالي"), "smishing": ("Smishing", "التصيّد عبر الرسائل النصية"),
 "vishing": ("Vishing", "التصيّد الصوتي"), "attachments": ("Malicious attachments", "المرفقات الخبيثة"),
 "driveby": ("Drive-by downloads", "التنزيلات الخفية"), "passwords": ("Password security", "أمان كلمات المرور"),
 "mfa": ("Multi-factor authentication", "المصادقة متعددة العوامل"), "credentials": ("Credential theft", "سرقة بيانات الدخول"),
 "social": ("Social engineering", "الهندسة الاجتماعية"), "privacy": ("Privacy and oversharing", "الخصوصية والإفراط في المشاركة"),
 "wifi": ("Public Wi-Fi", "شبكات الواي فاي العامة"), "sniffing": ("Network sniffing", "التنصّت على الشبكة"),
 "mitm": ("Man-in-the-middle", "هجوم الوسيط"), "malware": ("Malware", "البرمجيات الخبيثة"),
 "usb": ("USB baiting", "الطُّعم عبر USB"), "quishing": ("QR-code phishing", "التصيّد عبر رموز QR"),
 "spear": ("Spear phishing and spoofing", "التصيّد الموجّه وانتحال النطاق"), "ransomware": ("Ransomware", "برمجيات الفدية"),
 "session": ("Session hijacking", "اختطاف الجلسات"), "incident": ("Incident reporting", "الإبلاغ عن الحوادث"),
}
Q = [
(1,"phishing",1,
 ("Lina, a university student, gets an email that looks like it comes from the IT department. It says her account will be suspended in two hours unless she confirms her credentials, and it links to a login page that looks identical to the university portal.",
  ["Open the link and inspect the login page carefully before typing anything.","Go to the portal by typing its address yourself and look for notices.","Reply to the email and ask the sender to confirm the request is genuine.","Forward the email to a classmate to see whether she received it too."],
  "Phishing","Phishing combines urgency with a convincing copy of a trusted site. Leaving the message and reaching the service through an address you type or a saved bookmark is safe, because nothing in the email can steer you.",
  ["Merely loading a fake page can expose you to harmful scripts, and a perfect look proves nothing. The risk is judging the page instead of leaving it.","","Your reply goes to the attacker, who will happily confirm. Never verify a message through the same channel it arrived on.","Forwarding spreads the lure, and a classmate saying 'me too' proves nothing; you may both be targeted."]),
 ("تتلقى لينا، وهي طالبة جامعية، بريدًا إلكترونيًا يبدو أنه من قسم تقنية المعلومات. تقول الرسالة إن حسابها سيُعلَّق خلال ساعتين ما لم تؤكد بيانات دخولها، وتتضمن رابطًا إلى صفحة تسجيل دخول تطابق بوابة الجامعة تمامًا.",
  ["تفتح الرابط وتفحص صفحة الدخول جيدًا قبل كتابة أي شيء.","تدخل إلى البوابة بكتابة عنوانها بنفسها وتبحث عن إشعارات.","تردّ على الرسالة وتطلب من المرسل تأكيد صحة الطلب.","تحوّل الرسالة إلى زميلة لتعرف إن كانت وصلتها أيضًا."],
  "التصيّد الاحتيالي (Phishing)","يجمع التصيّد بين الاستعجال ونسخة مقنعة من موقع موثوق. ترك الرسالة والوصول إلى الخدمة عبر عنوان تكتبه بنفسك أو إشارة مرجعية محفوظة هو الأسلم، لأن شيئًا في البريد لا يستطيع توجيهك.",
  ["مجرد فتح صفحة مزيّفة قد يعرّضك لبرمجيات ضارة، ومظهرها المطابق لا يثبت شيئًا. الخطأ هو الحكم على الصفحة بدل مغادرتها.","","ردّك يصل إلى المحتال وسيؤكد لك الطلب بكل سرور. لا تتحقق من رسالة عبر القناة نفسها التي وصلت منها.","التحويل ينشر الطُّعم، وقول زميلتك «وصلتني أيضًا» لا يثبت شيئًا؛ فقد تكونان مستهدفتين معًا."])),
(1,"smishing",3,
 ("Omar gets an SMS: 'Your parcel is held at the depot. Pay a small customs fee to release it,' followed by a short link. He is waiting for an online order, but the message names neither the store nor the item.",
  ["Pay the small fee quickly, since the delivery is expected anyway.","Reply STOP so the sender removes his number from their list.","Open the link in a private browser window so nothing is saved.","Check the order in the store's or courier's official app."],
  "Smishing (SMS phishing)","Smishing uses delivery fees, fines and prize alerts because people act fast on texts. Even when you expect a parcel, a message that names no store or item is generic. Check the order in an app or site you already trust.",
  ["A small fee is the hook; the real goal is your card details, which can be reused later.","Replying confirms your number is active and read, which usually brings more messages.","A private window does not stop a fake page from collecting what you type.",""]),
 ("يتلقى عمر رسالة نصية: «طردك محتجز في المستودع. ادفع رسوم جمركية بسيطة للإفراج عنه»، يليها رابط قصير. هو ينتظر فعلًا طلبًا من متجر إلكتروني، لكن الرسالة لا تذكر اسم المتجر ولا المنتج.",
  ["يدفع الرسوم البسيطة بسرعة، فالتوصيل متوقع على أي حال.","يردّ بكلمة STOP كي يحذف المرسل رقمه من قائمته.","يفتح الرابط في نافذة تصفح خاص حتى لا يُحفظ شيء.","يتحقق من الطلب في تطبيق المتجر أو شركة الشحن الرسمي."],
  "التصيّد عبر الرسائل النصية (Smishing)","يعتمد هذا الهجوم على رسوم التوصيل والمخالفات وإشعارات الجوائز لأن الناس يتصرفون بسرعة مع الرسائل النصية. حتى لو كنت تنتظر طردًا، فالرسالة التي لا تذكر متجرًا أو منتجًا رسالة عامة. تحقق من الطلب عبر تطبيق أو موقع تثق به مسبقًا.",
  ["الرسوم الصغيرة هي الطُّعم؛ الهدف الحقيقي بيانات بطاقتك التي يمكن إعادة استخدامها لاحقًا.","الردّ يؤكد أن رقمك فعّال ويُقرأ، وغالبًا ما يجلب المزيد من الرسائل.","التصفح الخاص لا يمنع صفحة مزيّفة من جمع ما تكتبه.",""])),
(1,"vishing",0,
 ("A caller says she works in your bank's fraud department. She knows your name and the last four digits of your card, says a suspicious payment is in progress, and asks you to read out the six-digit code you are about to receive by SMS so she can block it.",
  ["Hang up, then call the number on your bank card to ask about the alert.","Read her the code, since she already knows details only the bank would have.","Ask her to prove her identity by telling you your full account balance.","Tell her you will read the code only after she emails you an official notice."],
  "Vishing (voice phishing)","Vishing callers build trust with a few real details and create panic. A one-time code approves an action, and a real bank never asks you to read it out. Ending the call and dialling the number on your card puts you back in control.",
  ["","Those details are easy to buy or collect from earlier leaks. The code lets the attacker approve their own action.","Scammers can often see some account details, and staying on the call keeps you under their control.","Emails can be forged, and you would remain on a call she is steering. End it and use a number you trust."]),
 ("تتصل بك امرأة تقول إنها من قسم مكافحة الاحتيال في مصرفك. تعرف اسمك وآخر أربعة أرقام من بطاقتك، وتقول إن عملية دفع مشبوهة جارية، وتطلب منك قراءة الرمز المكوّن من ستة أرقام الذي سيصلك برسالة نصية لتوقفها.",
  ["تنهي المكالمة ثم تتصل بالرقم المطبوع على بطاقتك لتسأل عن التنبيه.","تقرأ لها الرمز، فهي تعرف تفاصيل لا يعرفها إلا المصرف.","تطلب منها إثبات هويتها بذكر رصيد حسابك كاملًا.","تخبرها أنك لن تقرأ الرمز إلا بعد أن ترسل لك إشعارًا رسميًا بالبريد."],
  "التصيّد الصوتي (Vishing)","يبني المحتالون الثقة بتفاصيل حقيقية قليلة ثم يصنعون الذعر. الرمز لمرة واحدة يوافق على عملية ما، والمصرف الحقيقي لا يطلب منك قراءته. إنهاء المكالمة والاتصال بالرقم المطبوع على بطاقتك يعيد إليك زمام الأمور.",
  ["","هذه التفاصيل يسهل شراؤها أو جمعها من تسريبات سابقة. والرمز يمنح المهاجم موافقة على عمليته.","قد يرى المحتالون بعض بيانات الحساب، وبقاؤك على الخط يبقيك تحت سيطرتهم.","البريد يمكن تزويره، وستبقى على مكالمة تقودها هي. أنهِها واستخدم رقمًا تثق به."])),
(1,"attachments",2,
 ("Sara works in accounts. An email from a supplier she has dealt with before has an attachment named Invoice_2291.docm and the line 'See attached, payment overdue.' The supplier normally sends PDF invoices, the message arrived at 3 a.m., and the file asks her to 'Enable content' to view it.",
  ["Open it in Protected View and read it without enabling anything.","Save it to the desktop and scan it with antivirus before opening it.","Phone the supplier on a known number to ask whether they sent it.","Open it, and enable content only if the invoice amount looks familiar."],
  "Malicious attachment","Attackers hijack or imitate real suppliers, and 'Enable content' on an office file can launch hidden macros. A short call to a known number settles whether the invoice is real before any file is opened.",
  ["Protected View reduces risk, but it is not a guarantee, and the document is built to push you to enable content. Verify first.","A scan only catches known threats; new malware often passes. The real question is whether the sender is genuine.","","An amount can be copied from a genuine invoice. Enabling content is exactly what runs the hidden macro."]),
 ("تعمل سارة في قسم الحسابات. وصلها بريد من مورّد تعاملت معه سابقًا يحمل مرفقًا باسم Invoice_2291.docm وعبارة «مرفق الفاتورة، السداد متأخر». المورّد يرسل فواتيره عادةً بصيغة PDF، ووصلت الرسالة في الثالثة فجرًا، والملف يطلب منها «تمكين المحتوى» لعرضه.",
  ["تفتحه في وضع العرض المحمي وتقرأه دون تمكين أي شيء.","تحفظه على سطح المكتب وتفحصه بمضاد الفيروسات قبل فتحه.","تتصل بالمورّد على رقم معروف وتسأله إن كان قد أرسله.","تفتحه وتمكّن المحتوى فقط إذا بدا المبلغ مألوفًا."],
  "مرفق خبيث (Malicious attachment)","يخترق المهاجمون حسابات موردين حقيقيين أو ينتحلونها، وزر «تمكين المحتوى» في ملف مكتبي قد يشغّل ماكرو خفيًا. مكالمة قصيرة إلى رقم معروف تحسم صحة الفاتورة قبل فتح أي ملف.",
  ["العرض المحمي يقلل الخطر لكنه لا يضمنه، والملف مصمم لدفعك إلى تمكين المحتوى. تحقق أولًا.","الفحص يكشف التهديدات المعروفة فقط؛ كثير من البرمجيات الجديدة يمر. والسؤال الحقيقي: هل المرسل أصلي؟","","يمكن نسخ المبلغ من فاتورة حقيقية. وتمكين المحتوى هو بالضبط ما يشغّل الماكرو الخفي."])),
(1,"driveby",1,
 ("While reading a recipe blog, Yusuf's browser shows a full-page pop-up: 'Your browser is out of date and infected. Install the security update now.' A button downloads a file named BrowserUpdate.exe.",
  ["Install it, then run a scan afterwards in case something slipped through.","Close the tab, then update the browser from its own settings menu.","Click the pop-up's X to dismiss it, then keep browsing the blog.","Download the file but read reviews of the website before running it."],
  "Drive-by download / fake update","Fake update pop-ups imitate security warnings so that you run the malware yourself. Real browsers update through their own settings or automatically, never through a pop-up on a website.",
  ["Running the file is the infection. Scanning afterwards may come too late.","","The X can be fake, and staying on a page that serves such pop-ups keeps you exposed to automatic downloads.","Reviews of a blog do not make a pop-up file trustworthy. Real updates never arrive this way."]),
 ("أثناء قراءة مدوّنة وصفات، تظهر على متصفح يوسف نافذة منبثقة بملء الشاشة: «متصفحك قديم ومصاب. ثبّت التحديث الأمني الآن». ويحمّل زر فيها ملفًا باسم BrowserUpdate.exe.",
  ["يثبّته ثم يجري فحصًا لاحقًا تحسبًا لتسلل شيء ما.","يغلق التبويب ثم يحدّث المتصفح من قائمة إعداداته.","ينقر على علامة X في النافذة لإغلاقها ثم يواصل تصفح المدونة.","ينزّل الملف لكنه يقرأ تقييمات الموقع قبل تشغيله."],
  "التنزيل الخفي / التحديث المزيف","تقلّد هذه النوافذ تحذيرات الأمان كي تشغّل البرمجية الخبيثة بنفسك. المتصفحات الحقيقية تتحدث من إعداداتها أو تلقائيًا، وليس عبر نافذة منبثقة في موقع.",
  ["تشغيل الملف هو العدوى نفسها. والفحص بعد ذلك قد يأتي متأخرًا.","","علامة X قد تكون مزيّفة، والبقاء في صفحة تعرض مثل هذه النوافذ يبقيك عرضة لتنزيلات تلقائية.","تقييمات المدونة لا تجعل ملف النافذة موثوقًا. التحديثات الحقيقية لا تصل بهذه الطريقة."])),
(2,"passwords",0,
 ("Noor receives a notice that a forum she used years ago was breached. She uses the same password, with a small change at the end, for her email, her shopping account and her banking app.",
  ["Give every account its own password, stored in a password manager.","Change only the forum password, since that is where the breach happened.","Keep her base password and change one number at the end for each account.","Wait and watch for suspicious activity before changing anything."],
  "Password reuse (credential stuffing)","After a breach, attackers automatically try the leaked password and its small variations on email, shops and banks. Only unique passwords contain the damage, and a password manager makes that practical. Start with email and banking.",
  ["","Attackers test breached passwords on other sites, so the reused ones stay exposed.","Predictable variations are guessed by the same tools. Each password must be independent.","Credential stuffing is automated and usually succeeds long before you notice anything."]),
 ("تصل نور رسالة تفيد بتسريب بيانات منتدى استخدمته قبل سنوات. وهي تستعمل كلمة المرور نفسها، مع تعديل بسيط في آخرها، لبريدها الإلكتروني وحساب التسوق وتطبيق مصرفها.",
  ["تمنح كل حساب كلمة مرور خاصة به وتحفظها في مدير كلمات مرور.","تغيّر كلمة مرور المنتدى فقط، فهناك حدث التسريب.","تبقي كلمتها الأساسية وتغيّر رقمًا واحدًا في آخرها لكل حساب.","تنتظر وترصد أي نشاط مشبوه قبل أن تغيّر شيئًا."],
  "إعادة استخدام كلمة المرور (Credential stuffing)","بعد أي تسريب يجرّب المهاجمون كلمة المرور المسرّبة وتعديلاتها البسيطة تلقائيًا على البريد والمتاجر والمصارف. وحدها كلمات المرور الفريدة تحصر الضرر، ومدير كلمات المرور يجعل ذلك عمليًا. ابدأ بالبريد والمصرف.",
  ["","يختبر المهاجمون كلمات المرور المسرّبة على مواقع أخرى، فتبقى المكررة مكشوفة.","التعديلات المتوقعة تخمّنها الأدوات نفسها. يجب أن تكون كل كلمة مستقلة.","هذا الهجوم آلي وينجح عادةً قبل أن تلاحظ أي شيء بوقت طويل."])),
(2,"mfa",2,
 ("Karim's phone buzzes at midnight with a sign-in approval request for his work account, but he is not logging in. Ten minutes later it buzzes again, then again, and a chat message from 'IT support' asks him to approve one so the alerts stop.",
  ["Approve one request so the alerts stop, then change his password in the morning.","Turn off the phone's notifications until morning.","Deny every request, change his password now, and report it to the real IT team.","Reply to the chat message and ask the person to confirm they work in IT."],
  "MFA fatigue attack","In an MFA fatigue attack the criminal already knows your password and floods you with prompts, sometimes adding a fake support message, hoping you will approve one. Deny every unexpected prompt, change the password and tell the real IT team.",
  ["Approving gives the attacker immediate access. This is exactly what the flood of prompts is designed to achieve.","Silencing the phone hides the attack but does not stop it, and the password is probably already known.","","The chat message is part of the attack. An identity claim in the same channel proves nothing."]),
 ("يهتز هاتف كريم عند منتصف الليل بطلب موافقة على تسجيل دخول لحساب عمله، وهو لا يسجّل الدخول. بعد عشر دقائق يهتز مجددًا ثم مرة أخرى، وتصله رسالة دردشة من «الدعم التقني» تطلب منه الموافقة على طلب واحد لتتوقف التنبيهات.",
  ["يوافق على طلب واحد لتتوقف التنبيهات ثم يغيّر كلمة مروره صباحًا.","يوقف إشعارات الهاتف حتى الصباح.","يرفض كل الطلبات، ويغيّر كلمة مروره الآن، ويبلّغ فريق تقنية المعلومات الحقيقي.","يردّ على رسالة الدردشة ويطلب من صاحبها تأكيد أنه يعمل في الدعم التقني."],
  "هجوم إرهاق المصادقة (MFA fatigue)","في هذا الهجوم يعرف المجرم كلمة مرورك مسبقًا ويغرقك بطلبات الموافقة، وأحيانًا برسالة دعم مزيّفة، على أمل أن توافق على أحدها. ارفض كل طلب غير متوقع، وغيّر كلمة المرور، وأبلغ فريق التقنية الحقيقي.",
  ["الموافقة تمنح المهاجم دخولًا فوريًا، وهذا بالضبط ما صُمم سيل الطلبات لتحقيقه.","كتم الهاتف يخفي الهجوم ولا يوقفه، وكلمة المرور غالبًا معروفة أصلًا.","","رسالة الدردشة جزء من الهجوم. ادعاء الهوية في القناة نفسها لا يثبت شيئًا."])),
(2,"credentials",3,
 ("Dana checks her email on a computer in a print shop. As she finishes, she notices a small plastic device between the keyboard cable and the PC that was not there when she arrived.",
  ["Log out of her email and clear the browser history before leaving.","Tell the owner, then check her email again later to see if anything looks odd.","Remove the device and take it with her as evidence for the police.","Tell the owner, then reset her email password from her own phone."],
  "Credential theft (hardware keylogger)","A hardware keylogger records everything typed on a shared computer, and removing it does not erase what was already recorded. Change the password from a device you trust, review recent sign-ins and turn on MFA so a stolen password is not enough.",
  ["Logging out and clearing history does not undo keystrokes that were already captured.","Waiting gives the thief time to use the password. Act before anything looks odd.","Removing the device does not erase what it recorded; her password is still exposed.",""]),
 ("تفحص دانة بريدها الإلكتروني على حاسوب في مطبعة. وعند انتهائها تلاحظ جهازًا بلاستيكيًا صغيرًا بين سلك لوحة المفاتيح والحاسوب لم يكن موجودًا حين وصلت.",
  ["تسجّل الخروج من بريدها وتمسح سجل التصفح قبل المغادرة.","تخبر صاحب المحل ثم تعيد فحص بريدها لاحقًا لترى إن كان هناك ما يثير الريبة.","تنزع الجهاز وتأخذه معها كدليل.","تخبر صاحب المحل ثم تعيد ضبط كلمة مرور بريدها من هاتفها الشخصي."],
  "سرقة بيانات الدخول (Keylogger مادي)","يسجّل هذا الجهاز كل ما يُكتب على الحاسوب المشترك، ونزعه لا يمحو ما سُجّل. غيّر كلمة المرور من جهاز تثق به، وراجع عمليات الدخول الأخيرة، وفعّل المصادقة متعددة العوامل لتصبح كلمة المرور المسروقة غير كافية.",
  ["تسجيل الخروج ومسح السجل لا يلغيان ما التُقط من ضغطات المفاتيح.","الانتظار يمنح السارق وقتًا لاستخدام كلمة المرور. تصرّف قبل أن يبدو أي شيء مريبًا.","نزع الجهاز لا يمحو ما سجّله؛ كلمة مرورها ما زالت مكشوفة.",""])),
(2,"social",1,
 ("At a small office, a man in a courier jacket says he is from the IT contractor and has a ticket to fix the Wi-Fi. He carries a laptop and asks Reem, the receptionist, to let him into the server closet and to give him the admin password. He is polite and knows her manager's first name.",
  ["Let him in, but stay nearby and watch what he does during the visit.","Ask him to wait while she checks with her manager or the IT firm.","Give him the guest Wi-Fi password only and keep the server closet locked.","Ask to see his ID card and let him in if it looks professional."],
  "Social engineering (pretexting)","Pretexting wins trust with a uniform, a polite manner and a few real names. A visitor with a ticket should be confirmed with the company or manager through a number you already hold. Politeness is not verification.",
  ["Watching does not stop a quick plug-in or a photo. Access should not be granted before verification.","","Any access given to an unverified person is the foothold he is after.","ID cards are easy to fake. Verification has to come from the company through a channel you already trust."]),
 ("في مكتب صغير، يقول رجل يرتدي سترة مندوب توصيل إنه من شركة الصيانة التقنية ومعه طلب إصلاح للواي فاي. يحمل حاسوبًا ويطلب من ريم، موظفة الاستقبال، أن تدخله غرفة الخوادم وتعطيه كلمة مرور المسؤول. هو مهذب ويعرف الاسم الأول لمديرها.",
  ["تدخله لكنها تبقى قريبة لتراقب ما يفعله.","تطلب منه الانتظار بينما تتأكد من مديرها أو من شركة الصيانة.","تعطيه كلمة مرور شبكة الضيوف فقط وتبقي غرفة الخوادم مقفلة.","تطلب رؤية بطاقته وتدخله إن بدت احترافية."],
  "الهندسة الاجتماعية (انتحال الصفة)","ينال المنتحل الثقة بزي رسمي وأسلوب مهذب وبضعة أسماء حقيقية. يجب تأكيد زائر معه طلب عمل من الشركة أو المدير عبر رقم تملكه مسبقًا. اللباقة ليست وسيلة تحقق.",
  ["المراقبة لا تمنع توصيلًا سريعًا لجهاز أو التقاط صورة. لا يُمنح الوصول قبل التحقق.","","أي وصول يُمنح لشخص لم يُتحقق منه هو موطئ القدم الذي يسعى إليه.","بطاقات الهوية يسهل تزويرها. التحقق يجب أن يأتي من الشركة عبر قناة تثق بها."])),
(2,"privacy",2,
 ("Mariam has just booked a trip and wants to share her excitement. Her draft post has a photo of her boarding pass, her home city tagged, and the line 'House empty for two weeks!' Her account is public.",
  ["Post it, but blur the passenger name on the boarding pass.","Post it to 'close friends' only, keeping the same details and photo.","Share the photos after the trip, without the boarding pass.","Post it as drafted, but switch off the location tagging feature."],
  "Oversharing","Boarding-pass barcodes contain booking data, and travel dates plus 'house empty' announce an opportunity to burglars and scammers. Share trips afterwards, and keep documents, tickets and exact dates out of photos.",
  ["The barcode still holds booking details, and the post still announces an empty house.","Screenshots travel beyond any friends list, and the boarding pass and empty house are still exposed.","","Without the tag, her city, dates and empty house are still public."]),
 ("حجزت مريم رحلة للتو وتريد مشاركة حماسها. مسودة منشورها تضم صورة بطاقة الصعود إلى الطائرة، ووسم مدينتها، وعبارة «البيت فارغ لأسبوعين!». حسابها عام.",
  ["تنشره لكنها تطمس اسمها على بطاقة الصعود.","تنشره للأصدقاء المقرّبين فقط بالتفاصيل نفسها.","تشارك الصور بعد الرحلة دون بطاقة الصعود.","تنشره كما هو مع إيقاف وسم الموقع."],
  "الإفراط في المشاركة (Oversharing)","يحمل رمز بطاقة الصعود بيانات الحجز، وتواريخ السفر مع «البيت فارغ» تعلن فرصة للصوص والمحتالين. شارك الرحلات بعد انتهائها، وأبقِ الوثائق والتذاكر والتواريخ الدقيقة خارج الصور.",
  ["الرمز ما زال يحمل بيانات الحجز، والمنشور ما زال يعلن أن البيت فارغ.","لقطات الشاشة تنتقل خارج أي قائمة أصدقاء، وتبقى بطاقة الصعود والبيت الفارغ مكشوفين.","","من دون الوسم، تبقى مدينتها وتواريخها وبيتها الفارغ معلنة للجميع."])),
(3,"wifi",3,
 ("At the airport Hani sees two open networks, 'Airport_Free_WiFi' and 'Airport Free WiFi 2'. He needs to check his bank balance before boarding.",
  ["Join the one with the stronger signal and use the bank's app, which encrypts its traffic.","Join either one and stay logged out of everything except the bank.","Join either one and switch on a free VPN app he finds in the app store.","Use his own mobile data for the bank and leave the airport networks alone."],
  "Public Wi-Fi risk (evil twin)","Attackers set up look-alike networks, known as evil twins, to sit between you and the internet. When you handle money or sensitive accounts, your own mobile data is a safer path than any open network.",
  ["Encryption helps, but a fake network can still interfere and capture other data. A safer option exists.","Being logged out elsewhere does not protect the bank session on an unverified network.","An unknown free VPN may log or sell your traffic, so it can be the interceptor itself.",""]),
 ("في المطار يرى هاني شبكتين مفتوحتين: «Airport_Free_WiFi» و«Airport Free WiFi 2». يحتاج إلى معرفة رصيده المصرفي قبل الصعود إلى الطائرة.",
  ["ينضم إلى الأقوى إشارة ويستخدم تطبيق المصرف الذي يشفّر بياناته.","ينضم إلى أي منهما ويبقى خارج كل الحسابات عدا المصرف.","ينضم إلى أي منهما ويشغّل تطبيق VPN مجانيًا وجده في المتجر.","يستخدم بيانات هاتفه للمصرف ويترك شبكات المطار."],
  "خطر الواي فاي العام (التوأم الشرير)","ينشئ المهاجمون شبكات مشابهة، تُعرف بالتوأم الشرير، لتقف بينك وبين الإنترنت. عند التعامل مع المال أو الحسابات الحساسة تكون بيانات هاتفك أأمن من أي شبكة مفتوحة.",
  ["التشفير يفيد، لكن الشبكة المزيّفة قد تتدخل وتلتقط بيانات أخرى. وهناك خيار أأمن.","الخروج من الحسابات الأخرى لا يحمي جلسة المصرف على شبكة لم يُتحقق منها.","تطبيق VPN مجهول قد يسجّل بياناتك أو يبيعها، فقد يكون هو المتنصّت.",""])),
(3,"sniffing",0,
 ("At a café, Laila signs in to her university's course site on the café's open Wi-Fi. The browser shows 'Not secure' beside the address, which starts with http:// instead of https://.",
  ["Stop, switch to mobile data, and log in only when the address uses https://.","Continue, since she is only checking course notes, not making payments.","Continue after refreshing the page, as the label sometimes appears by mistake.","Continue in a private window so the session is not stored."],
  "Network sniffing","On http:// sites, data travels unencrypted, so anyone on the same open network can read it with simple sniffing tools. Use https:// for logins or switch networks. A private window only hides history on your own device.",
  ["","Her login details would travel in readable form, and passwords are often reused on other services.","The label is accurate. Refreshing does not add encryption.","A private window hides history on her device, not the traffic on the network."]),
 ("في مقهى، تسجّل ليلى الدخول إلى موقع مقررات جامعتها عبر واي فاي المقهى المفتوح. يعرض المتصفح عبارة «غير آمن» بجوار العنوان الذي يبدأ بـ http:// بدل https://.",
  ["تتوقف وتنتقل إلى بيانات هاتفها ولا تسجّل الدخول إلا حين يبدأ العنوان بـ https://.","تتابع، فهي تطّلع على ملاحظات المقرر فقط ولا تدفع شيئًا.","تتابع بعد تحديث الصفحة، فالتنبيه يظهر أحيانًا بالخطأ.","تتابع في نافذة تصفح خاص حتى لا تُحفظ الجلسة."],
  "التنصّت على الشبكة (Sniffing)","في مواقع http:// تنتقل البيانات دون تشفير، فيستطيع أي شخص على الشبكة المفتوحة نفسها قراءتها بأدوات بسيطة. استخدم https:// لتسجيل الدخول أو غيّر الشبكة. التصفح الخاص يخفي السجل على جهازك فقط.",
  ["","ستنتقل بيانات دخولها بشكل مقروء، وكثيرًا ما تُستخدم كلمات المرور نفسها في خدمات أخرى.","التنبيه صحيح. وتحديث الصفحة لا يضيف تشفيرًا.","التصفح الخاص يخفي السجل على جهازها، لا الحركة على الشبكة."])),
(3,"mitm",1,
 ("In a hotel, Adel opens his bank's website on the hotel Wi-Fi. His browser blocks the page with a warning that the site's security certificate does not match the address, and offers an 'Advanced: proceed anyway' link. The same site loaded without any warning on his mobile data yesterday.",
  ["Proceed anyway, since the bank's address is spelled correctly in the bar.","Stop, switch to mobile data, and tell the bank about the warning.","Reload the page a few times to see if the warning goes away by itself.","Proceed and log in, but avoid making any transfers or payments."],
  "Man-in-the-middle attack","A certificate warning on a site that worked yesterday suggests someone may be intercepting the connection. Clicking through hands over your login. Leave the network, use mobile data and tell the bank.",
  ["A correct spelling is not the issue. A mismatch on a site that was fine yesterday points to interception.","","Reloading does not change the cause. A persistent warning is a red flag.","Logging in alone gives an interceptor your credentials and session, even with no transfers."]),
 ("في فندق، يفتح عادل موقع مصرفه عبر واي فاي الفندق. يحجب المتصفح الصفحة بتحذير من أن شهادة أمان الموقع لا تطابق العنوان، ويعرض رابط «متقدم: المتابعة على أي حال». وكان الموقع نفسه يعمل دون أي تحذير أمس على بيانات هاتفه.",
  ["يتابع على أي حال، فعنوان المصرف مكتوب بشكل صحيح.","يتوقف، وينتقل إلى بيانات هاتفه، ويبلّغ المصرف بالتحذير.","يعيد تحميل الصفحة عدة مرات ليرى إن كان التحذير سيختفي.","يتابع ويسجّل الدخول لكنه لا يجري أي تحويلات."],
  "هجوم الوسيط (Man-in-the-middle)","ظهور تحذير شهادة في موقع كان يعمل أمس يوحي بأن أحدًا قد يعترض الاتصال. والمتابعة رغم التحذير تسلّم بيانات دخولك. غادر الشبكة، واستخدم بيانات هاتفك، وأبلغ المصرف.",
  ["صحة الإملاء ليست المشكلة. عدم التطابق في موقع كان سليمًا أمس يشير إلى اعتراض.","","إعادة التحميل لا تغيّر السبب. والتحذير المستمر علامة خطر.","تسجيل الدخول وحده يعطي المعترِض بياناتك وجلستك، حتى دون أي تحويلات."])),
(3,"malware",3,
 ("Rania needs to edit a PDF urgently. A search result offers 'PDF Editor Pro, full version free, no licence needed' on a site she has never heard of. It downloads an installer, and Windows asks permission to make changes to her device.",
  ["Allow it, since her antivirus is running and would block anything dangerous.","Allow it, but disconnect from the internet while it installs.","Allow it, and uninstall it if the computer starts running slowly.","Cancel it and use a legitimate editor, even if the free version is limited."],
  "Malware (cracked software)","Free 'full versions' of paid software are a favourite way to spread info-stealers and remote-access trojans. Antivirus is a safety net, not permission. Use a trusted vendor, even if the free version is limited.",
  ["Antivirus is not perfect, and cracked installers are often built to evade it.","Installing offline still installs the malware; it activates when she reconnects.","Many threats run silently. Slowness is rarely the sign, and data may be gone by then.",""]),
 ("تحتاج رانيا إلى تعديل ملف PDF بشكل عاجل. تعرض لها نتيجة بحث «محرر PDF برو، النسخة الكاملة مجانًا دون ترخيص» على موقع لم تسمع به من قبل. ينزل مثبّت، ويطلب ويندوز إذنها لإجراء تغييرات على جهازها.",
  ["تسمح به، فمضاد الفيروسات يعمل وسيحجب أي شيء خطير.","تسمح به لكنها تقطع الإنترنت أثناء التثبيت.","تسمح به وتزيله إذا بدأ الحاسوب يعمل ببطء.","تلغيه وتستخدم محررًا شرعيًا حتى لو كانت نسخته المجانية محدودة."],
  "البرمجيات الخبيثة (البرامج المقرصنة)","النسخ «الكاملة» المجانية من البرامج المدفوعة وسيلة مفضلة لنشر برمجيات سرقة البيانات والتحكم عن بُعد. مضاد الفيروسات شبكة أمان وليس إذنًا. استخدم مصدرًا موثوقًا حتى لو كانت النسخة المجانية محدودة.",
  ["مضاد الفيروسات ليس معصومًا، ومثبّتات البرامج المقرصنة تُصمم غالبًا لتفاديه.","التثبيت دون إنترنت يثبّت البرمجية الخبيثة أيضًا، وتنشط عند إعادة الاتصال.","كثير من التهديدات يعمل بصمت. والبطء نادرًا ما يكون العلامة، وقد تضيع البيانات قبلها.",""])),
(3,"usb",0,
 ("Yacine finds a USB flash drive in the car park outside his office. It has a label reading 'Salary Review 2026 - Confidential'. He is curious whose it is.",
  ["Hand it to the IT or security team without plugging it in anywhere.","Plug it into an old personal laptop that has nothing important on it.","Plug it into his work computer so the antivirus can scan it automatically.","Leave it where he found it so the owner can come back for it."],
  "USB baiting","Attackers drop tempting USB drives because curiosity does the work. A plugged-in drive can act as a keyboard and run commands within seconds. Give it to the security team unplugged so they can handle it safely.",
  ["","Some devices act as keyboards and run commands at once, and the old laptop may still be signed in to accounts or your home network.","Some attacks act the moment the device connects, before any scan, and this is a company network.","Leaving it means someone else may plug it in, and a drive dropped at your office may be targeting it."]),
 ("يجد ياسين قرص USB في موقف السيارات أمام مكتبه. عليه ملصق مكتوب فيه «مراجعة الرواتب 2026 - سري». يتساءل بدافع الفضول لمن هو.",
  ["يسلّمه لفريق تقنية المعلومات أو الأمن دون توصيله بأي جهاز.","يوصله بحاسوب شخصي قديم لا يحوي شيئًا مهمًا.","يوصله بحاسوب العمل ليفحصه مضاد الفيروسات تلقائيًا.","يتركه حيث وجده ليعود صاحبه ويأخذه."],
  "الطُّعم عبر USB (USB baiting)","يترك المهاجمون أقراص USB مغرية لأن الفضول يؤدي المهمة. القرص الموصول قد يتصرف كلوحة مفاتيح وينفذ أوامر خلال ثوانٍ. سلّمه لفريق الأمن دون توصيله ليتعاملوا معه بأمان.",
  ["","بعض الأجهزة تتصرف كلوحات مفاتيح وتنفذ أوامر فورًا، وقد يكون الحاسوب القديم مسجّلًا دخوله إلى حسابات أو إلى شبكة منزلك.","بعض الهجمات يعمل لحظة التوصيل قبل أي فحص، وهذه شبكة الشركة.","تركه قد يدفع شخصًا آخر لتوصيله، وقرص أُسقط عند مكتبك قد يكون موجّهًا إليه."])),
(4,"quishing",2,
 ("A city car park has a new sticker on its parking meter: 'Pay by QR code and avoid fines.' Sarah notices the sticker is slightly raised at the edges and the other meters do not have one. When she scans it, her phone previews a web address she does not recognise, not the city council's.",
  ["Continue to the page, since the sticker is on an official-looking meter.","Continue, but pay with a prepaid card to limit any loss.","Skip it, pay via the council's app or a machine, and report the sticker.","Open the page and check for the padlock icon before entering card details."],
  "QR-code phishing (quishing)","A QR code hides its destination, so criminals stick fake ones over real ones. Preview the link, and when it looks wrong, pay through the official app or machine. The padlock only means the connection is encrypted, not that the site is honest.",
  ["Fake codes are stuck over genuine ones. Where a sticker sits proves nothing.","Limiting the amount does not stop her card data being captured and reused.","","Scam sites have padlocks too. It shows encryption, not honesty."]),
 ("في موقف سيارات بالمدينة ملصق جديد على عدّاد الوقوف: «ادفع عبر رمز QR وتجنّب المخالفات». تلاحظ سارة أن الملصق مرتفع قليلًا عند أطرافه وأن العدّادات الأخرى خالية منه. وعندما تمسحه، يعرض هاتفها معاينة لعنوان موقع لا تعرفه وليس عنوان البلدية.",
  ["تتابع إلى الصفحة، فالملصق على عدّاد يبدو رسميًا.","تتابع لكنها تدفع ببطاقة مدفوعة مسبقًا للحد من الخسارة.","لا تفتحه، وتدفع عبر تطبيق البلدية أو جهاز الدفع، وتبلّغ عن الملصق.","تفتح الصفحة وتتحقق من أيقونة القفل قبل إدخال بيانات البطاقة."],
  "التصيّد عبر رموز QR (Quishing)","رمز QR يخفي وجهته، لذا يلصق المجرمون رموزًا مزيّفة فوق الحقيقية. عاين الرابط، وإذا بدا غريبًا فادفع عبر التطبيق أو الجهاز الرسمي. القفل يعني أن الاتصال مشفّر فقط، لا أن الموقع صادق.",
  ["تُلصق الرموز المزيّفة فوق الحقيقية. ومكان الملصق لا يثبت شيئًا.","تقليل المبلغ لا يمنع التقاط بيانات بطاقتها وإعادة استخدامها.","","مواقع الاحتيال لها أقفال أيضًا. القفل يدل على التشفير لا على الصدق."])),
(4,"spear",3,
 ("Tariq is a finance officer. An email apparently from the CEO asks him to pay a new supplier by transfer today and to keep it confidential because the deal is still in progress. It mentions a real meeting from last week. Looking closely, the sender's address ends in '@acmecorp-finance.com', whereas the company uses '@acmecorp.com'.",
  ["Reply to the email and ask the CEO for the supplier's invoice before paying.","Make a small test payment first to see whether the account is genuine.","Pay it, but ask the CEO's assistant to approve it by email first.","Call the CEO on a known number and follow the payment approval process."],
  "Spear phishing and domain impersonation","Spear phishing is aimed at one person's role, using a look-alike domain, authority, secrecy and real details. Payment requests should be confirmed through a separate channel, such as a call to a known number, and follow approval rules regardless of who asks.",
  ["Your reply goes to the attacker, who will send a convincing fake invoice.","A test payment still sends money to the fraudster and builds trust for a larger request.","An approval by email stays inside the same fake or spoofed channel.",""]),
 ("طارق موظف في القسم المالي. يصله بريد يبدو أنه من المدير التنفيذي يطلب فيه دفع مبلغ لمورّد جديد بتحويل اليوم، مع إبقاء الأمر سريًا لأن الصفقة لم تكتمل. ويذكر اجتماعًا حقيقيًا جرى الأسبوع الماضي. وعند التدقيق ينتهي عنوان المرسل بـ acmecorp-finance.com@ بينما تستخدم الشركة acmecorp.com@.",
  ["يردّ على البريد ويطلب من المدير فاتورة المورّد قبل الدفع.","يجري دفعة تجريبية صغيرة أولًا ليرى إن كان الحساب حقيقيًا.","يدفع لكنه يطلب من مساعد المدير الموافقة عبر البريد.","يتصل بالمدير على رقم معروف ويتبع إجراءات الموافقة على الدفع."],
  "التصيّد الموجّه وانتحال النطاق (Spear phishing)","يستهدف التصيّد الموجّه دور شخص بعينه عبر نطاق مشابه وسلطة وسرّية وتفاصيل حقيقية. يجب تأكيد طلبات الدفع عبر قناة مستقلة، مثل مكالمة على رقم معروف، واتباع إجراءات الموافقة مهما كان الطالب.",
  ["ردّك يصل إلى المهاجم الذي سيرسل فاتورة مزوّرة مقنعة.","الدفعة التجريبية ترسل المال إلى المحتال وتبني الثقة لطلب أكبر.","الموافقة بالبريد تبقى داخل القناة المزيّفة أو المنتحلة نفسها.",""])),
(4,"ransomware",0,
 ("On Monday morning, Hala's computer shows a message saying her files are locked and demanding a cryptocurrency payment within 48 hours. The computer is connected to the office network and shared drive, and the office backups sit on a drive that is also connected.",
  ["Unplug the network cable or turn off Wi-Fi, don't pay, and call IT now.","Restart the computer to see if the message disappears, then try opening her files.","Pay the ransom quickly since the deadline is short and the amount is modest.","Delete the ransom note and start restoring files from the connected backup drive."],
  "Ransomware","The first minutes decide the damage. Disconnect the machine to stop spread, do not pay (it funds criminals and guarantees nothing), leave the machine as it is for investigators, and let IT restore from clean, isolated backups.",
  ["","Restarting can trigger further encryption and destroys evidence while the infection keeps spreading.","Payment guarantees nothing, funds criminals and marks you as a payer, while the infection remains.","A connected backup can be encrypted too, and restoring before containment can reinfect everything."]),
 ("صباح الاثنين، يعرض حاسوب هالة رسالة تقول إن ملفاتها مقفلة وتطلب دفعًا بالعملة الرقمية خلال 48 ساعة. الحاسوب متصل بشبكة المكتب والقرص المشترك، والنسخ الاحتياطية للمكتب على قرص متصل أيضًا.",
  ["تفصل كابل الشبكة أو توقف الواي فاي، ولا تدفع، وتتصل بفريق التقنية فورًا.","تعيد تشغيل الحاسوب لترى إن كانت الرسالة ستختفي ثم تحاول فتح ملفاتها.","تدفع الفدية بسرعة فالمهلة قصيرة والمبلغ معقول.","تحذف رسالة الفدية وتبدأ استعادة الملفات من قرص النسخ الاحتياطي المتصل."],
  "برمجيات الفدية (Ransomware)","الدقائق الأولى تحدد حجم الضرر. افصل الجهاز لوقف الانتشار، ولا تدفع (فالدفع يموّل المجرمين ولا يضمن شيئًا)، واترك الجهاز كما هو للمحققين، ودع فريق التقنية يستعيد من نسخ احتياطية نظيفة ومعزولة.",
  ["","إعادة التشغيل قد تطلق مزيدًا من التشفير وتُتلف الأدلة بينما تواصل العدوى انتشارها.","الدفع لا يضمن شيئًا ويموّل المجرمين ويضعك في قائمة الدافعين، والعدوى باقية.","النسخة الاحتياطية المتصلة قد تُشفَّر أيضًا، والاستعادة قبل الاحتواء قد تعيد العدوى إلى كل شيء."])),
(4,"session",2,
 ("Ines installed a free 'coupon finder' browser extension. A week later her online shop account sends an alert about a sign-in from another country, even though she never shared her password and her account uses multi-factor authentication that was never prompted.",
  ["Change only the account password, since that is what blocks the intruder.","Add a stronger MFA method and keep using the extension as before.","Remove the extension, end every session, then change her passwords.","Log out on her own computer and carry on using the shop as before."],
  "Session hijacking (cookie theft)","Malicious extensions can steal session cookies, which prove you are already signed in, so the attacker bypasses both password and MFA. Remove the extension, sign out everywhere to cancel sessions, then change passwords from a clean device.",
  ["A stolen session often stays valid after a password change unless all sessions are revoked.","MFA does not help once a session is already authenticated, and the extension keeps capturing.","","Logging out locally does not end the attacker's session on the server, and the extension remains."]),
 ("ثبّتت إينيس إضافة مجانية للمتصفح لـ«إيجاد القسائم». بعد أسبوع يرسل حسابها في المتجر الإلكتروني تنبيهًا بتسجيل دخول من بلد آخر، رغم أنها لم تشارك كلمة مرورها وأن حسابها يستخدم مصادقة متعددة العوامل لم تُطلب منها.",
  ["تغيّر كلمة مرور الحساب فقط، فهذا يمنع المتسلل.","تضيف وسيلة مصادقة أقوى وتواصل استخدام الإضافة.","تزيل الإضافة، وتُنهي كل الجلسات، ثم تغيّر كلمات مرورها.","تسجّل الخروج على حاسوبها وتواصل كما كانت."],
  "اختطاف الجلسات (سرقة ملفات تعريف الجلسة)","قد تسرق الإضافات الخبيثة ملفات الجلسة التي تثبت أنك مسجّل دخولك مسبقًا، فيتجاوز المهاجم كلمة المرور والمصادقة معًا. أزل الإضافة، وأنهِ الجلسات في كل مكان، ثم غيّر كلمات المرور من جهاز نظيف.",
  ["الجلسة المسروقة تبقى غالبًا صالحة بعد تغيير كلمة المرور ما لم تُلغَ كل الجلسات.","المصادقة لا تفيد بعد أن تصبح الجلسة موثّقة، والإضافة تواصل الالتقاط.","","تسجيل الخروج محليًا لا ينهي جلسة المهاجم على الخادم، والإضافة باقية."])),
(4,"incident",1,
 ("Moments after entering her work credentials on a page reached through a delivery-notice email, Laith realises the page was fake. Nothing seems to have happened and no one has noticed. His account has access to client files, and he worries he will be blamed.",
  ["Change his password at once and tell no one, since the matter is closed.","Report it to the security team now and change his password as advised.","Wait a few days to see if anything strange happens before bothering the team.","Delete the email so no one else opens it and carry on working."],
  "Incident reporting and response","Quick reporting limits damage: the team can reset access, look for forwarding rules and warn colleagues who received the same email. A hidden incident costs far more than an honest mistake, so report early.",
  ["A silent fix hides the incident. The attacker may already have used the access, and colleagues may have the same email.","","Delay gives the attacker time. The speed of response limits the damage.","Deleting removes evidence and leaves colleagues unwarned."]),
 ("بعد لحظات من إدخال بيانات عمله في صفحة وصل إليها عبر بريد «إشعار توصيل»، يدرك ليث أن الصفحة مزيّفة. لا يبدو أن شيئًا حدث ولم يلاحظ أحد. حسابه يتيح الوصول إلى ملفات العملاء، وهو قلق من أن يُلام.",
  ["يغيّر كلمة مروره فورًا ولا يخبر أحدًا، فالأمر انتهى.","يبلّغ فريق الأمن فورًا ويغيّر كلمة مروره بحسب إرشاداتهم.","ينتظر أيامًا ليرى إن كان سيحدث شيء غريب قبل أن يزعج الفريق.","يحذف البريد كي لا يفتحه أحد آخر ويواصل عمله."],
  "الإبلاغ عن الحوادث والاستجابة لها","الإبلاغ السريع يحد من الضرر: يستطيع الفريق إعادة ضبط الوصول، والبحث عن قواعد إعادة التوجيه، وتحذير الزملاء الذين وصلهم البريد نفسه. الحادث المخفي أكلف بكثير من خطأ صادق، فبادر بالإبلاغ.",
  ["الإصلاح الصامت يخفي الحادث. قد يكون المهاجم استخدم الوصول فعلًا، وقد يكون لدى زملائه البريد نفسه.","","التأخير يمنح المهاجم وقتًا. وسرعة الاستجابة تحدّ من الضرر.","الحذف يزيل الأدلة ويترك الزملاء بلا تحذير."])),
]
